/* eslint-env serviceworker */

/**
 * The service worker.
 *
 * What it is for: the catalog is a single multi-megabyte file, and downloading it again on
 * every visit would be both slow and rude on a metered connection. Cached, the app opens
 * instantly and searches with no network at all -- which is the state a phone is actually
 * in inside a broadcast facility, a basement studio, or a scrum.
 *
 * Deliberately hand-written rather than generated by a build plugin. There is no precache
 * manifest to keep in sync because nothing here enumerates hashed filenames: navigations are
 * network-first, everything else same-origin is cache-first, and cross-origin is not the
 * worker's business at all.
 *
 * The cache is versioned by a query parameter the page passes at registration (see
 * main.tsx), so shipping a new build installs a new worker and evicts the old catalog. A
 * constant in this file would have to be remembered and bumped by hand, which means one day
 * it would not be.
 */

const VERSION = new URL(self.location.href).searchParams.get('v') ?? 'dev';
const CACHE = `gis-browser-mobile-${VERSION}`;

self.addEventListener('install', (event) => {
  // The shell only. The catalog is big and is cached on first use instead, so an install
  // triggered in the background cannot spend somebody's data plan without being asked.
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(['./', './index.html', './manifest.webmanifest']))
      // A shell file that 404s on a partial deploy must not wedge the worker in "installing"
      // forever; the fetch handler can still populate the cache at runtime.
      .catch(() => undefined)
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) => Promise.all(names.filter((n) => n !== CACHE).map((n) => caches.delete(n))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  /*
   * Boundary services are left entirely alone.
   *
   * They are cross-origin, their responses are large, and several of them are opaque to a
   * service worker anyway. More to the point, a cached boundary is a boundary whose vintage
   * the app can no longer vouch for -- and this app's whole job is being able to say where
   * a shape came from and when. lib/geometry.ts keeps fetched geometry for the session, in
   * memory, where its lifetime is obvious.
   */
  if (url.origin !== self.location.origin) return;

  // Navigations are network-first: a deployed fix should appear on the next launch, not
  // whenever the browser happens to feel like updating. Falling back to the cached shell is
  // what makes the app open at all when offline.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          void caches.open(CACHE).then((cache) => cache.put('./index.html', copy));
          return response;
        })
        .catch(() => caches.match('./index.html').then((hit) => hit ?? caches.match('./'))),
    );
    return;
  }

  // Everything else same-origin -- hashed bundles, icons, the catalog -- is cache-first.
  // Their names change when their content does, so a hit is never stale.
  event.respondWith(
    caches.match(request).then((hit) => {
      if (hit) return hit;
      return fetch(request).then((response) => {
        // Only complete, successful responses are stored. Caching a 206 or an error page
        // under the catalog's URL would produce an app that fails identically forever.
        if (response.ok && response.status === 200) {
          const copy = response.clone();
          void caches.open(CACHE).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    }),
  );
});
